#include <iostream>

int main() {
    int origen[5]{8, 0, -3, 7, 2};
    int copia[4]{90, 91, 92, 93};
    const int capacidadOrigen =
        static_cast<int>(sizeof origen / sizeof origen[0]);
    const int capacidadCopia =
        static_cast<int>(sizeof copia / sizeof copia[0]);
    int cantidad = 0;
    int indice = 0;
    int nuevo = 0;
    if (!(std::cin >> cantidad >> indice >> nuevo)) {
        return 1;
    }

    bool aceptado = false;
    if (cantidad >= 0 && cantidad <= capacidadOrigen
        && cantidad <= capacidadCopia
        && indice >= 0 && indice < capacidadOrigen) {
        for (int i = 0; i < cantidad; ++i) {
            copia[i] = origen[i];
        }
        origen[indice] = nuevo;
        aceptado = true;
    }

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Origen=";
    for (int i = 0; i < capacidadOrigen; ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << origen[i];
    }
    std::cout << '\n' << "Copia=";
    for (int i = 0; i < capacidadCopia; ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << copia[i];
    }
    std::cout << '\n';
    return 0;
}

