#include <cstddef>
#include <iostream>

int main() {
    int datos[3]{6, -2, 4};
    const std::size_t cantidad = sizeof datos / sizeof datos[0];

    for (std::size_t pendientes = cantidad; pendientes > 0; --pendientes) {
        const std::size_t indice = pendientes - 1;
        if (pendientes != cantidad) {
            std::cout << ':';
        }
        std::cout << datos[indice];
    }
    return 0;
}
